      const pl = osc('sine', 0.047), plg = gain(140); pl.connect(plg); plg.connect(A.padF.frequency); pl.start(t);
      // the swimming leviathan: a dark water rush that follows its speed
      const sw = brown(true), sf = filt('lowpass', 140, 0.9);
