      const t = now(), L = A.level;
      due('nextBreath', t, A.breath, () => [7, 6.6, 6.2, 5.8, 5.4, 5][L] + rnd(0, 1.2));
      due('nextPad', t, A.padSwell, () => rnd(7.5, 9.5));
      due('nextMoan', t, A.moan, () => rnd(15, 24) - L * 1.5);
      // sonar tones disabled: the owner turned the sonar ping off as too noisy
      // hull creaks get more frequent with depth; the Core has a slow heartbeat
      if (Math.random() < 0.006 + 0.008 * L) A.creak();
      if (L >= 5 && !A.beatAt) A.beatAt = t;
      if (L >= 5 && t > A.beatAt) { A.heartbeat(t + 0.05); A.beatAt = t + 1.15; }
      if (L < 5) A.beatAt = 0;
